-- warehouse_graph.json -> PostgreSQL import
-- Target warehouse_id: 1
-- Safe to rerun: nodes are upserted and generated edges are recreated.

BEGIN;

CREATE UNIQUE INDEX IF NOT EXISTS ux_warehouse_node_warehouse_code
ON warehouse_node (warehouse_id, node_code)
WHERE node_code IS NOT NULL;

DELETE FROM warehouse_edge e
USING warehouse_node f, warehouse_node t
WHERE e.from_node_id = f.node_id
  AND e.to_node_id = t.node_id
  AND f.warehouse_id = 1
  AND t.warehouse_id = 1
  AND f.node_code IS NOT NULL
  AND t.node_code IS NOT NULL;



COMMIT;

SELECT (SELECT COUNT(*) FROM warehouse_node WHERE warehouse_id = 1 AND node_code IS NOT NULL) AS imported_nodes, (SELECT COUNT(*) FROM warehouse_edge e JOIN warehouse_node f ON f.node_id=e.from_node_id JOIN warehouse_node t ON t.node_id=e.to_node_id WHERE f.warehouse_id=1 AND t.warehouse_id=1 AND f.node_code IS NOT NULL AND t.node_code IS NOT NULL) AS imported_edges;